  function randomName() {
    if (Math.random() < 0.5)
      return "Mr. " + random(maleNames);
    if (Math.random() < 0.5)
      return "Mrs. " + random(femaleNames);
    return "Miss. " + random(femaleNames);
  }
  function random(arr) {
    return arr[Math.floor(Math.random() * arr.length)];
  }
  var FONT;
  function loadFont(font) {
    FONT = font;
  }

  // src/Input.ts
  var import_miglib3 = __toESM(require_dist());
  var PAD = 0;
  var DEADZONE = 0.2;
  var Input = class {
    static car() {
      return import_miglib3.Keys.justPressed(import_miglib3.Keys.KEY_C) || import_miglib3.Gamepads.wasButtonPressed(PAD, import_miglib3.GamepadButton.Y);
    }
    static move() {
      let x = 0;
      let y = 0;
      if (import_miglib3.Keys.isDown(import_miglib3.Keys.KEY_A)) x -= 1;
      if (import_miglib3.Keys.isDown(import_miglib3.Keys.KEY_D)) x += 1;
      if (import_miglib3.Keys.isDown(import_miglib3.Keys.KEY_W)) y -= 1;
      if (import_miglib3.Keys.isDown(import_miglib3.Keys.KEY_S)) y += 1;
      if (import_miglib3.Gamepads.isButtonDown(PAD, import_miglib3.GamepadButton.DPAD_LEFT)) x -= 1;
      if (import_miglib3.Gamepads.isButtonDown(PAD, import_miglib3.GamepadButton.DPAD_RIGHT)) x += 1;
      if (import_miglib3.Gamepads.isButtonDown(PAD, import_miglib3.GamepadButton.DPAD_UP)) y -= 1;
      if (import_miglib3.Gamepads.isButtonDown(PAD, import_miglib3.GamepadButton.DPAD_DOWN)) y += 1;
      const stick = import_miglib3.Gamepads.getLeftStick(PAD);
      if (stick.length() > DEADZONE) {
        x += stick.x;
        y += stick.y;
      }
      const dir = new import_miglib3.Vec2(x, y);
      const len = dir.length();
      if (len < 1e-4) return new import_miglib3.Vec2(0, 0);
      return len > 1 ? dir.normalize() : dir;
    }
    static interactPressed() {
      return import_miglib3.Keys.justPressed(import_miglib3.Keys.KEY_E) || import_miglib3.Gamepads.wasButtonPressed(PAD, import_miglib3.GamepadButton.A);
    }
    static menuPressed() {
      return import_miglib3.Keys.justPressed(import_miglib3.Keys.KEY_Q) || import_miglib3.Gamepads.wasButtonPressed(PAD, import_miglib3.GamepadButton.B);
    }
  };

  // src/Dialog.ts
  var MAX_INTERACT_CD = 160;
  var Dialog = class {
    // private onDone?: () => void;
    constructor() {
      this.charsPerSecond = 30;
      this.width = 950;
      this.height = 150;
      this.padding = 24;
      this.textSize = 24;
      this.textColor = WHITE;
      this.parts = [];
      this.partIndex = 0;
      this.revealed = 0;
      this.selectedOption = 0;
      this.lastOptionSelected = null;
      this.interactCooldown = 0;
    }
    get hasParts() {
      return this.partIndex < this.parts.length;
    }
    showEasy(text) {
      this.show([{ text: () => text }]);
    }
    show(parts) {
      if (this.hasParts) {
        this.parts.splice(this.partIndex + 1, 0, ...parts);
        return;
      }
      this.parts = [...parts];
      this.partIndex = 0;
      this.revealed = 0;
      this.selectedOption = 0;
      this.interactCooldown = MAX_INTERACT_CD;
      this.lastOptionSelected = null;
    }
    // private skipParts(): void {
    //     while (this.hasParts && this.parts[this.partIndex].skip?.()) this.goNext();
    // }
    update(g, dt) {
      if (!this.hasParts) return;
      const part = this.parts[this.partIndex];
      const text = part.text();
      const textLength = text.length;
      this.revealed = Math.min(this.revealed + this.charsPerSecond * dt, textLength);
      if (part.options && part.callback && this.revealed >= textLength) {
        this.handleOption(g, part, text, textLength);
      } else {
        this.handleNormal(g, part, text, textLength);
      }
    }
    handleOption(g, part, text, textLength) {
      if (this.interactCooldown > 0) {
        this.interactCooldown -= g.deltaTime;
        return;
      }
      const mv = Input.move();
      if (mv.x > 0) {
        this.selectedOption = Math.max(0, Math.min(part.options.length - 1, this.selectedOption + 1));
        this.interactCooldown = MAX_INTERACT_CD;
      }
      if (mv.x < 0) {
        this.selectedOption = Math.max(0, Math.min(part.options.length - 1, this.selectedOption - 1));
        this.interactCooldown = MAX_INTERACT_CD;
      }
      if (!Input.interactPressed()) return;
      this.lastOptionSelected = this.selectedOption;
      part.callback(this.selectedOption);
      this.goNext();
    }
    handleNormal(g, part, text, textLength) {
      if (!Input.interactPressed()) return;
      if (this.revealed < textLength) {
        this.revealed = textLength;
        return;
      }
      if (part.callback) part.callback(0);
      this.goNext();
    }
    goNext() {
      this.partIndex++;
      this.revealed = 0;
      if (!this.hasParts) {
      }
    }
    render(g) {
      if (!this.hasParts) return;
      const part = this.parts[this.partIndex];
      const w = this.width;
      const h = this.height;
      const x = Math.floor(g.width / 2 - w / 2);
      const y = Math.floor(g.height - h - 8);
      g.render9patch("patch", x, y, w, h, { scale: ZOOM });
      const s = g.sketch;
      s.push();
      const lines = this.wrap(g, part.text(), w - this.padding * 2);
      const lineHeight = this.textSize * 1.25;
      let remaining = Math.floor(this.revealed);
      for (let i = 0; i < lines.length && remaining > 0; i++) {
        g.renderText(lines[i].slice(0, remaining), x + this.padding, y + this.textSize + this.padding + i * lineHeight, { size: this.textSize, color: this.textColor });
        remaining -= lines[i].length;
      }
      s.pop();
      if (part.options) {
        let dx = 0;
        const ox = x + 24;
        const oy = y + h - 8 - this.textSize;
        for (let i = 0; i < part.options.length; i++) {
          let opt = part.options[i];
          if (i === this.selectedOption) opt = "[" + opt + "]";
          else opt = " " + opt + " ";
          g.renderText(opt, ox + dx, oy, { size: this.textSize, color: this.textColor });
          dx += 50 + g.textWidth(opt, { size: this.textSize });
        }
      }
    }
    wrap(g, text, maxWidth) {
      const lines = [];
      let line = "";
      for (const word of text.split(/(?<=\s)/)) {
        if (line && g.textWidth(line + word, { size: this.textSize }) > maxWidth) {
          lines.push(line);
          line = "";
        }
        line += word;
      }
      if (line) lines.push(line);
      return lines;
    }
  };

