  // src/LetterGen.ts
  function shuffle(array) {
    let currentIndex = array.length, randomIndex;
    while (currentIndex != 0) {
      randomIndex = Math.floor(Math.random() * currentIndex);
      currentIndex--;
      [array[currentIndex], array[randomIndex]] = [
        array[randomIndex],
        array[currentIndex]
      ];
    }
    return array;
  }
  var LetterGen = class {
    constructor(data) {
      this.data = data;
      this.streetIds = Object.keys(STREETS);
    }
    genLetters() {
      const allPossibleHouses = this.streetIds.map((id) => STREETS[id]).filter((s) => s.difficulty !== null && s.difficulty <= this.data.daysPassed).map((s) => s.houses).reduce((acc, v) => acc.concat(v), []);
      return shuffle(allPossibleHouses).splice(0, this.nOfLetters()).map((houseId) => {
        return {
          houseId,
          from: randomName(),
          to: random(HOUSES_BY_ID[houseId].residents)
        };
      });
    }
    nOfLetters() {
      if (this.data.daysPassed < 2) return 3;
      if (this.data.daysPassed < 5) return 4;
      return 6 + Math.random() * (this.data.daysPassed - 4);
    }
  };

